INSERT INTO `paragon_blessing` (`sigil`, `effect`, `value`, `value2`, `chance`, `duration`, `cooldown`, `scope`, `name`, `description`) VALUES
    (1, 8, 5, 0, 0, 0, 0, 1, 'Bénédiction de Khaz''goroth', 'Augmente les dégâts de vos attaques d''arme de 5%.'),
    (2, 12, 15, 35, 0, 0, 0, 1, 'Bénédiction de Tyr', 'Les dégâts de vos attaques d''arme sont augmentés de 15% contre les cibles sous 35% de vie.'),
    (3, 17, 25, 8, 15, 0, 1500, 1, 'Bénédiction d''Aggramar', 'Vos attaques d''arme ont 15% de chances d''infliger aussi 25% de leurs dégâts à 4 autres ennemis au plus, à moins de 8 mètres de votre cible. 1,5 s de recharge.'),
    (4, 16, 1, 10, 50, 15000, 0, 1, 'Bénédiction d''Odyn', 'Tuer un ennemi d''une attaque d''arme a 50% de chances d''augmenter les dégâts de vos attaques d''arme de 1% pendant 15 s, cumulable 10 fois. Chaque victime relance la durée.'),
    (5, 11, 100, 0, 6, 0, 0, 1, 'Bénédiction de Thorim', '6% de chances que vos attaques d''arme infligent 100% de dégâts supplémentaires. Les chances de double frappe s''additionnent, jusqu''à 25%.'),
